  const nextLesson = currentIndex < allLessons.length - 1 ? allLessons[currentIndex + 1] : null;

  // Tính % tiến độ hoàn thành khóa học (chỉ tính các bài học thuộc khóa học đang xem)
  const totalLessonsCount = allLessons.length;
