  const completedCount = useMemo(
    () => completedIds.filter((id) => courseLessonIds.has(id)).length,
    [completedIds, courseLessonIds]
  );
  const progressPercent =
    totalLessonsCount > 0
      ? Math.min(100, Math.round((completedCount / totalLessonsCount) * 100))
