                <ul className="space-y-1">
                  {module.lessons.map((lesson) => {
                    const isActive = activeLesson.id === lesson.id;
                    const isLessonCompleted = completedIds.includes(lesson.id);
                    const canAccessThis = !lesson.isVIP || isUserVIP;

                    return (
