                <p className="text-[10px] text-amber-700/80 dark:text-amber-400/80 mt-0.5">Lập luận chuyên sâu</p>
              </div>
            </div>

            {/* Sàn TMĐT & Tên Shop */}
            <div className="grid grid-cols-2 gap-2.5">
