                  }`}
                >
                  <span className="text-base">🛒</span>
                  <div className="text-left">
                    <div className="font-bold leading-tight">Shopee</div>
                    <div className="text-[10px] font-normal opacity-80">Tiêu đề ≤ 120 ký tự</div>
