                />
              </div>
            </div>

            {/* 4. ĐIỂM NỔI BẬT (USP) & TAGS */}
            <div>
              <div className="flex items-center justify-between mb-1.5">
                <label className="block text-xs font-bold text-slate-700 dark:text-slate-300">
