                </label>
                <span className="text-[10px] text-slate-400">
                  {charCount(inputs.usp)}/{SEO_LIMITS.usp}
                </span>
              </div>
              <textarea
                rows={3}
                value={inputs.usp}
                onChange={(e) => setInputs((prev) => ({ ...prev, usp: e.target.value }))}
