      usersTimeline,
    ] = await Promise.all([
      prisma.user.count(),
      prisma.user.count({ where: { isVIP: true } }),
      prisma.lesson.count(),
      prisma.course.count(),
      prisma.transaction.aggregate({
        where: { status: "SUCCESS" },
        _sum: { amount: true },
      }),
      prisma.transaction.count({ where: { status: "SUCCESS" } }),
      prisma.user.findMany({
        orderBy: { createdAt: "desc" },
