/**
 * Server Action: Kiểm tra thử nghiệm OpenAI API Key xem có kết nối được không
 */
export async function testOpenAiConnectionAction(params: {
  apiKey: string;
  model?: string;
  baseUrl?: string;
}) {
  try {
    const cleanKey = params.apiKey?.trim().replace(/^["']|["']$/g, "");
    if (!cleanKey) {
      return {
        success: false,
        error: "Vui lòng nhập OpenAI API Key trước khi kiểm tra.",
      };
    }

    const cleanBaseUrl = params.baseUrl?.trim() || undefined;
    const testModel = params.model?.trim() || "gpt-4o-mini";

    const testClient = new OpenAI({
      apiKey: cleanKey,
      baseURL: cleanBaseUrl,
      timeout: 12000,
    });

    // Gửi 1 test prompt siêu ngắn (max 5 tokens) để xác thực key và model
    const response = await testClient.chat.completions.create({
      model: testModel,
      messages: [{ role: "user", content: "ping" }],
      max_tokens: 5,
    });

    return {
      success: true,
      message: `Kết nối thành công! Key hợp lệ và Model '${testModel}' phản hồi tốt.`,
      sampleReply: response.choices[0]?.message?.content || "OK",
    };
  } catch (error: any) {
    console.error("OpenAI test connection error:", error);

    let friendlyError = error?.message || "Không thể kết nối đến OpenAI.";
    if (error?.status === 401) {
      friendlyError = "Lỗi xác thực (401): API Key không chính xác hoặc đã bị thu hồi.";
    } else if (error?.status === 429) {
      friendlyError = "Lỗi hạn ngạch (429): Tài khoản OpenAI của bạn đã hết Credits (Quota) hoặc bị giới hạn Rate Limit.";
    } else if (error?.status === 404) {
      friendlyError = `Model '${params.model || "gpt-4o-mini"}' không tồn tại hoặc tài khoản không có quyền truy cập.`;
    } else if (error?.code === "ECONNREFUSED" || friendlyError.includes("fetch failed")) {
      friendlyError = "Lỗi kết nối mạng: Không thể liên lạc với máy chủ OpenAI hoặc Base URL không hợp lệ.";
    }

    return {
      success: false,
      error: friendlyError,
    };
  }
}

/**
 * Server Action: Đổi mật khẩu tài khoản ADMIN
 */
export async function changeAdminPasswordAction(params: {
  currentPassword: string;
  newPassword: string;
  confirmPassword: string;
}) {
  try {
    const currentPassword = params.currentPassword?.trim() || "";
    const newPassword = params.newPassword?.trim() || "";
    const confirmPassword = params.confirmPassword?.trim() || "";

    if (!currentPassword) {
      return { success: false, error: "Vui lòng nhập mật khẩu Admin hiện tại." };
    }

    if (!newPassword) {
      return { success: false, error: "Vui lòng nhập mật khẩu mới." };
    }

    if (newPassword.length < 6) {
      return { success: false, error: "Mật khẩu mới phải có tối thiểu 6 ký tự." };
    }

    if (newPassword !== confirmPassword) {
      return { success: false, error: "Xác nhận mật khẩu mới không khớp!" };
    }

    const { changeAdminPassword } = await import("@/lib/system-settings");
    const result = await changeAdminPassword(currentPassword, newPassword);

    if (!result.success) {
      return { success: false, error: result.error || "Không thể đổi mật khẩu Admin." };
    }

    revalidatePath("/admin/settings");
    revalidatePath("/admin");

    return {
      success: true,
      message: "Đổi mật khẩu ADMIN thành công! Mật khẩu mới có hiệu lực ngay lập tức.",
    };
  } catch (error: any) {
    console.error("Error changing admin password:", error);
    return {
      success: false,
      error: error?.message || "Lỗi hệ thống khi đổi mật khẩu Admin.",
    };
  }
}

"use server";

import { prisma } from "@/lib/prisma";
import crypto from "crypto";
import { revalidatePath } from "next/cache";

function hashPassword(password: string) {
  return crypto.createHash("sha256").update(password).digest("hex");
}

import { calculateNewVipExpiration } from "@/lib/sepay-server";

// Bật / Tắt trạng thái VIP nhanh
export async function toggleUserVip(userId: string, newVipStatus: boolean) {
  try {
    const user = await prisma.user.findUnique({ where: { id: userId } });
    if (!user) return { success: false, error: "Người dùng không tồn tại" };

    let newExpiresAt = user.vipExpiresAt;
    if (newVipStatus) {
      // Nếu bật VIP và hiện tại vipExpiresAt đã quá hạn thì reset về null (hoặc gia hạn)
      if (user.vipExpiresAt && new Date(user.vipExpiresAt).getTime() <= Date.now()) {
        newExpiresAt = null; // Mặc định chuyển sang VIP vĩnh viễn khi Admin bấm Lên VIP
      }
    }

    const updated = await prisma.user.update({
      where: { id: userId },
      data: {
        isVIP: newVipStatus,
        vipExpiresAt: newVipStatus ? newExpiresAt : null,
      },
    });

    revalidatePath("/admin/users");
    revalidatePath("/admin");
    revalidatePath("/profile");
    return {
      success: true,
      isVIP: updated.isVIP,
      vipExpiresAt: updated.vipExpiresAt ? updated.vipExpiresAt.toISOString() : null,
    };
  } catch (error) {
    console.error("Error toggling VIP:", error);
    return { success: false, error: "Không thể cập nhật trạng thái VIP" };
  }
}

// Điều chỉnh thời hạn VIP (Thêm ngày, Trọn đời, Hạ FREE, hoặc ngày tùy chỉnh)
export async function updateUserVipDuration(
  userId: string,
  action: "add_days" | "lifetime" | "expire_now" | "custom_date",
  days?: number,
  customDate?: string
) {
  try {
    const user = await prisma.user.findUnique({ where: { id: userId } });
    if (!user) return { success: false, error: "Người dùng không tồn tại" };

    let newExpiresAt: Date | null = null;
    let newIsVIP = true;

    if (action === "lifetime") {
      newExpiresAt = null;
      newIsVIP = true;
    } else if (action === "expire_now") {
      newExpiresAt = new Date(Date.now() - 1000 * 60); // Quá hạn
      newIsVIP = false;
    } else if (action === "add_days") {
      const addedDays = Number(days) || 30;
      newExpiresAt = calculateNewVipExpiration(user.vipExpiresAt, user.isVIP, addedDays);
      newIsVIP = true;
    } else if (action === "custom_date" && customDate) {
      const parsed = new Date(customDate);
      if (isNaN(parsed.getTime())) {
        return { success: false, error: "Ngày tùy chỉnh không hợp lệ" };
      }
      newExpiresAt = parsed;
      newIsVIP = parsed.getTime() > Date.now();
    }

    const updated = await prisma.user.update({
      where: { id: userId },
      data: {
        isVIP: newIsVIP,
        vipExpiresAt: newExpiresAt,
      },
    });

    revalidatePath("/admin/users");
    revalidatePath("/admin");
    revalidatePath("/profile");

    return {
      success: true,
      user: {
        id: updated.id,
        isVIP: updated.isVIP,
        vipExpiresAt: updated.vipExpiresAt ? updated.vipExpiresAt.toISOString() : null,
      },
    };
  } catch (error: any) {
    console.error("Error updating VIP duration:", error);
    return { success: false, error: error?.message || "Không thể cập nhật thời hạn VIP" };
  }
}

