import { prisma } from "@/lib/prisma";
import { UsersManager } from "@/components/admin/UsersManager";
import { syncAllExpiredVipUsers } from "@/lib/sepay-server";
import { computeVipDaysLeft } from "@/lib/vip-expiration";
import { getActiveVipPlans } from "@/lib/vip-plans-server";
import { getStartOfTodayVn } from "@/lib/ai-usage";
import type { Metadata } from "next";

export const dynamic = "force-dynamic";

export const metadata: Metadata = {
  title: "Quản Lý Người Dùng & Học Viên",
  description: "Quản lý danh sách tài khoản học viên, cấp quyền VIP, phân bổ lượt dùng AI và đổi mật khẩu người dùng.",
};

export default async function AdminUsers() {
  try {
    // Tự động kiểm tra và hạ cấp các tài khoản đã hết hạn VIP về FREE
    await syncAllExpiredVipUsers();

    const startOfToday = getStartOfTodayVn();

    const [users, vipPlans] = await Promise.all([
      prisma.user.findMany({
        orderBy: { createdAt: "desc" },
        select: {
          id: true,
          email: true,
          name: true,
          phone: true,
          role: true,
          isVIP: true,
          vipExpiresAt: true,
          isLocked: true,
          createdAt: true,
          userCredit: {
            select: { balance: true },
          },
        },
      }),
      getActiveVipPlans(),
    ]);

    // Lấy định mức lượt Free mỗi ngày an toàn (tương thích cả khi client dev cache)
    const freeLimitsMap = new Map<string, number>();
    let globalDailyFreeLimit = 12;
    try {
      const [rawLimits, settingRows]: [any, any] = await Promise.all([
        (prisma as any).$queryRawUnsafe('SELECT id, "dailyFreeLimit" FROM "User"'),
        (prisma as any).$queryRawUnsafe(
          'SELECT "defaultDailyFreeLimit" FROM "SystemSetting" WHERE id = \'default\' LIMIT 1;'
        ),
      ]);

      if (Array.isArray(rawLimits)) {
        rawLimits.forEach((row) => {
          if (row.id) {
            freeLimitsMap.set(row.id, Number(row.dailyFreeLimit) || 12);
          }
        });
      }

      if (settingRows && settingRows[0]?.defaultDailyFreeLimit !== undefined) {
        globalDailyFreeLimit = Number(settingRows[0].defaultDailyFreeLimit) || 12;
      }
    } catch (err) {
      console.warn("Could not query dailyFreeLimit via raw SQL:", err);
    }

    const todayUsageMap = new Map<string, number>();
    try {
      if (typeof (prisma as any).aiUsageLog?.groupBy === "function") {
        const todayUsages = await (prisma as any).aiUsageLog.groupBy({
          by: ["userId"],
          where: { createdAt: { gte: startOfToday } },
          _count: { id: true },
        });
        todayUsages.forEach((u: any) => {
          todayUsageMap.set(u.userId, u._count?.id || 0);
        });
      } else {
        const rows: any = await prisma.$queryRawUnsafe(
          'SELECT "userId", COUNT(*)::int as count FROM "AiUsageLog" WHERE "createdAt" >= $1 GROUP BY "userId"',
          startOfToday
        );
        rows.forEach((r: any) => {
          todayUsageMap.set(r.userId, Number(r.count) || 0);
        });
      }
    } catch (err) {
      console.warn("Could not query aiUsageLog groupBy, trying raw SQL:", err);
      try {
        const rows: any = await prisma.$queryRawUnsafe(
          'SELECT "userId", COUNT(*)::int as count FROM "AiUsageLog" WHERE "createdAt" >= $1 GROUP BY "userId"',
          startOfToday
        );
        rows.forEach((r: any) => {
          todayUsageMap.set(r.userId, Number(r.count) || 0);
        });
      } catch (sqlErr) {
        console.warn("Could not query aiUsageLog via raw SQL:", sqlErr);
      }
    }

    const serializedUsers = users.map((u: any) => {
      const usedToday = todayUsageMap.get(u.id) || 0;
      const dailyLimit = freeLimitsMap.get(u.id) ?? u.dailyFreeLimit ?? globalDailyFreeLimit ?? 12;
      const remainingFree = u.isVIP ? null : Math.max(0, dailyLimit - usedToday);

      return {
        ...u,
        dailyFreeLimit: dailyLimit,
        remainingFree,
        usedToday,
        createdAt: u.createdAt ? u.createdAt.toISOString() : new Date().toISOString(),
        vipExpiresAt: u.vipExpiresAt ? u.vipExpiresAt.toISOString() : null,
        vipDaysLeft: computeVipDaysLeft(u.vipExpiresAt),
      };
    });

    return (
      <UsersManager
        initialUsers={serializedUsers}
        initialPlans={vipPlans}
        initialGlobalFreeLimit={globalDailyFreeLimit}
      />
    );
  } catch (error: any) {
    console.error("ADMIN USERS ERROR:", error);
    return (
      <div className="p-8 text-red-500 bg-red-50 rounded-xl border border-red-200">
        <h2 className="text-xl font-bold mb-2">Error loading users:</h2>
        <pre className="text-sm whitespace-pre-wrap">{error?.stack || error?.message || String(error)}</pre>
      </div>
    );
  }
}

"use client";

import { useState } from "react";
import {
  Crown,
  Plus,
  Edit2,
  Trash2,
  Star,
  CheckCircle2,
  XCircle,
  RefreshCw,
  Sparkles,
  Zap,
  Check,
  X,
  Layers,
  ArrowUpDown,
  AlertCircle,
  HelpCircle,
} from "lucide-react";
import { AdminPageHeader } from "@/components/admin/AdminPageHeader";
import {
  createVipPlan,
  updateVipPlan,
  toggleVipPlanActive,
  toggleVipPlanPopular,
  deleteVipPlan,
  seedDefaultVipPlans,
} from "./actions";
import type { VipPlanItem } from "@/lib/vip-plans";

interface Props {
  initialPlans: VipPlanItem[];
}

export default function VipPlansManager({ initialPlans }: Props) {
  const [plans, setPlans] = useState<VipPlanItem[]>(initialPlans);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingPlan, setEditingPlan] = useState<VipPlanItem | null>(null);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [statusMessage, setStatusMessage] = useState<{ type: "success" | "error"; text: string } | null>(null);

  // Form State
  const [formData, setFormData] = useState({
    name: "",
    slug: "",
    price: 299000,
    originalPrice: 499000,
    period: "/ tháng",
    durationDays: 30,
    desc: "",
    tag: "",
    isPopular: false,
    order: 1,
    active: true,
  });
  const [featuresList, setFeaturesList] = useState<string[]>([
    "Không giới hạn 8 công cụ AI bán hàng",
    "Mở khóa toàn bộ 27 video Masterclass",
    "Xuất file Excel tính giá & thuế sàn",
    "Hỗ trợ kỹ thuật viên 1-1 qua Zalo",
  ]);
  const [newFeatureInput, setNewFeatureInput] = useState("");

  const activeCount = plans.filter((p) => p.active).length;
  const popularPlan = plans.find((p) => p.isPopular);

  const openCreateModal = () => {
    setEditingPlan(null);
    setFormData({
      name: "",
      slug: "",
      price: 299000,
      originalPrice: 499000,
      period: "/ tháng",
      durationDays: 30,
      desc: "Trải nghiệm sức mạnh toàn bộ công cụ AI và khóa học",
      tag: "Gói Mới",
      isPopular: false,
      order: plans.length + 1,
      active: true,
    });
    setFeaturesList([
      "Không giới hạn 8 công cụ AI bán hàng",
      "Mở khóa toàn bộ 27 video Masterclass",
      "Xuất file Excel tính giá & thuế sàn",
      "Hỗ trợ kỹ thuật viên 1-1 qua Zalo",
    ]);
    setIsModalOpen(true);
  };

  const openEditModal = (plan: VipPlanItem) => {
    setEditingPlan(plan);
    setFormData({
      name: plan.name,
      slug: plan.slug,
      price: plan.price,
      originalPrice: plan.originalPrice,
      period: plan.period,
      durationDays: plan.durationDays ?? 0,
      desc: plan.desc,
      tag: plan.tag ?? "",
      isPopular: plan.isPopular,
      order: plan.order,
      active: plan.active,
    });
    setFeaturesList(Array.isArray(plan.features) ? [...plan.features] : []);
    setIsModalOpen(true);
  };

  const handleAddFeature = () => {
    if (!newFeatureInput.trim()) return;
    setFeaturesList([...featuresList, newFeatureInput.trim()]);
    setNewFeatureInput("");
  };

  const handleRemoveFeature = (index: number) => {
    setFeaturesList(featuresList.filter((_, i) => i !== index));
  };

  const handleToggleActive = async (plan: VipPlanItem) => {
    const res = await toggleVipPlanActive(plan.id, plan.active);
    if (res.success) {
      setPlans(plans.map((p) => (p.id === plan.id ? { ...p, active: res.active! } : p)));
      setStatusMessage({ type: "success", text: `Đã ${res.active ? "bật hiển thị" : "tạm ẩn"} gói '${plan.name}'` });
    } else {
      setStatusMessage({ type: "error", text: res.error || "Không thể đổi trạng thái" });
    }
  };

  const handleTogglePopular = async (plan: VipPlanItem) => {
    const res = await toggleVipPlanPopular(plan.id, plan.isPopular);
    if (res.success) {
      setPlans(plans.map((p) => (p.id === plan.id ? { ...p, isPopular: res.isPopular! } : p)));
      setStatusMessage({
        type: "success",
        text: `Đã ${res.isPopular ? "gắn nhãn Best-Seller cho" : "bỏ nhãn Best-Seller của"} gói '${plan.name}'`,
      });
    } else {
      setStatusMessage({ type: "error", text: res.error || "Không thể đổi nhãn nổi bật" });
    }
  };

  const handleDelete = async (plan: VipPlanItem) => {
    if (!confirm(`Bạn có chắc chắn muốn xóa vĩnh viễn gói '${plan.name}' không?`)) {
      return;
    }
    const res = await deleteVipPlan(plan.id);
    if (res.success) {
      setPlans(plans.filter((p) => p.id !== plan.id));
      setStatusMessage({ type: "success", text: res.message || "Đã xóa gói VIP" });
    } else {
      setStatusMessage({ type: "error", text: res.error || "Không thể xóa gói" });
    }
  };

  const handleResetDefaults = async () => {
    if (!confirm("Khôi phục danh sách 3 gói VIP mặc định (1 Tháng, 1 Năm, Trọn Đời)?")) {
      return;
    }
    setIsSubmitting(true);
    const res = await seedDefaultVipPlans();
    setIsSubmitting(false);
    if (res.success) {
      window.location.reload();
    } else {
      setStatusMessage({ type: "error", text: res.error || "Lỗi khi khôi phục" });
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.name.trim()) {
      alert("Vui lòng nhập tên gói VIP");
      return;
    }

    setIsSubmitting(true);
    setStatusMessage(null);

    try {
      if (editingPlan) {
        // Cập nhật gói
        const res = await updateVipPlan(editingPlan.id, {
          name: formData.name,
          slug: formData.slug,
          price: Number(formData.price),
          originalPrice: Number(formData.originalPrice),
          period: formData.period,
          durationDays: Number(formData.durationDays),
          desc: formData.desc,
          tag: formData.tag,
          isPopular: formData.isPopular,
          order: Number(formData.order),
          active: formData.active,
          features: featuresList,
        });

        if (res.success && res.data) {
          setPlans(plans.map((p) => (p.id === editingPlan.id ? (res.data as VipPlanItem) : p)));
          setIsModalOpen(false);
          setStatusMessage({ type: "success", text: `Đã cập nhật gói '${formData.name}' thành công!` });
        } else {
          setStatusMessage({ type: "error", text: res.error || "Cập nhật thất bại" });
        }
      } else {
        // Tạo gói mới
        const res = await createVipPlan({
          name: formData.name,
          slug: formData.slug,
          price: Number(formData.price),
          originalPrice: Number(formData.originalPrice),
          period: formData.period,
          durationDays: Number(formData.durationDays),
          desc: formData.desc,
          tag: formData.tag,
          isPopular: formData.isPopular,
          order: Number(formData.order),
          active: formData.active,
          features: featuresList,
        });

        if (res.success && res.data) {
          setPlans([...plans, res.data as VipPlanItem].sort((a, b) => a.order - b.order));
          setIsModalOpen(false);
          setStatusMessage({ type: "success", text: `Đã thêm mới gói '${formData.name}' thành công!` });
        } else {
          setStatusMessage({ type: "error", text: res.error || "Tạo mới thất bại" });
        }
      }
    } catch (err) {
      console.error(err);
      setStatusMessage({ type: "error", text: "Đã xảy ra lỗi hệ thống" });
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <div className="space-y-6">
      {/* ── HEADER ──────────────────────────────────────────────────────────── */}


      {/* ── STATUS MESSAGE ──────────────────────────────────────────────────── */}
      {statusMessage && (
        <div
          className={`p-4 rounded-2xl text-xs font-medium flex items-center justify-between gap-3 ${statusMessage.type === "success"
            ? "bg-emerald-50 text-emerald-800 border border-emerald-200"
            : "bg-rose-50 text-rose-800 border border-rose-200"
            }`}
        >
          <div className="flex items-center gap-2">
            {statusMessage.type === "success" ? (
              <CheckCircle2 size={18} className="text-emerald-600 shrink-0" />
            ) : (
              <AlertCircle size={18} className="text-rose-600 shrink-0" />
            )}
            <span>{statusMessage.text}</span>
          </div>
          <button onClick={() => setStatusMessage(null)} className="text-slate-400 hover:text-slate-600 cursor-pointer">
            <X size={14} />
          </button>
        </div>
