      errorCode = "EXPIRED_QUOTA";
      errorMessage = "Tài khoản OpenAI đã hết hạn ngạch (Hết Credits/tiền) hoặc bị giới hạn lượt gọi (Lỗi 429). Vui lòng nạp thêm Credits hoặc đổi Token khác.";
    }
