        "Nội Dung": sections.zalo || result,
      },
    ];

    const worksheet = XLSX.utils.json_to_sheet(rows);
    worksheet["!cols"] = [
      { wch: 6 },
      { wch: 22 },
      { wch: 35 },
      { wch: 40 },
      { wch: 30 },
