};

/**
 * Lấy mốc 00:00:00 của ngày hôm nay theo múi giờ Việt Nam (GMT+7)
 */
export function getStartOfTodayVn(): Date {
  const now = new Date();
  const vnDateStr = new Intl.DateTimeFormat("en-CA", {
    timeZone: "Asia/Ho_Chi_Minh",
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
  }).format(now);
  return new Date(`${vnDateStr}T00:00:00+07:00`);
}

/**
 * Định dạng thời gian thân thiện (tiếng Việt)
 */
export function formatRelativeTime(dateInput: Date | string): string {
  const date = typeof dateInput === "string" ? new Date(dateInput) : dateInput;
  const now = new Date();
  const diffMs = now.getTime() - date.getTime();
  const diffSec = Math.floor(diffMs / 1000);
  const diffMin = Math.floor(diffSec / 60);
  const diffHour = Math.floor(diffMin / 60);
  const diffDay = Math.floor(diffHour / 24);

  if (diffSec < 60) return "Vừa xong";
  if (diffMin < 60) return `${diffMin} phút trước`;
  if (diffHour < 24) return `${diffHour} giờ trước`;
  if (diffDay === 1) return "Hôm qua";
  if (diffDay < 7) return `${diffDay} ngày trước`;

  return new Intl.DateTimeFormat("vi-VN", {
    timeZone: "Asia/Ho_Chi_Minh",
    day: "2-digit",
    month: "2-digit",
    year: "numeric",
  }).format(date);
}

/**
 * Tự động tạo tóm tắt hành động từ công cụ và thông số đầu vào
 */
export function summarizeAiAction(tool: string, inputs: any): string {
  switch (tool) {
    case "seo-optimizer":
      return inputs?.productName
        ? `Tối ưu SEO & Hashtag cho "${inputs.productName}"`
        : "Tối ưu SEO & Hashtag sản phẩm";

    case "script-writer":
      return inputs?.productName
        ? `Kịch bản video TikTok: "${inputs.productName}"`
        : "Tạo kịch bản video TikTok/Reels";

    case "appeal-generator":
      return inputs?.shopName
        ? `Đơn kháng nghị vi phạm: Shop ${inputs.shopName}`
        : "Tạo đơn kháng nghị vi phạm sàn TMĐT";

    case "ad-copy":
      return inputs?.productName
        ? `Mẫu quảng cáo Ads: "${inputs.productName}"`
        : "Tạo mẫu quảng cáo & Hook 3s đa kênh";

    case "review-replier":
      return inputs?.shopName
        ? `Phản hồi đánh giá ${inputs.rating || 5} sao: Shop ${inputs.shopName}`
        : `Phản hồi đánh giá ${inputs?.rating || 5} sao của khách`;

    case "chat-broadcast":
      return inputs?.shopName
        ? `Tin nhắn CSKH / Broadcast: Shop ${inputs.shopName}`
        : "Soạn kịch bản tin nhắn chăm sóc khách hàng";

    case "title-spinner":
      return inputs?.originalTitle
        ? `Xoay tiêu đề: "${inputs.originalTitle.slice(0, 45)}${inputs.originalTitle.length > 45 ? "..." : ""}"`
        : "Nhân bản tiêu đề chống spam";

    case "video-repurposer":
      return inputs?.videoTopic
        ? `Tái bản video 5 kênh: "${inputs.videoTopic.slice(0, 40)}${inputs.videoTopic.length > 40 ? "..." : ""}"`
        : "Tái bản video 5 kênh đa nền tảng";

    case "pricing-calculator":
      return inputs?.productName
        ? `Định giá sản phẩm "${inputs.productName}"`
        : "Định giá bán & tối ưu lợi nhuận";

    case "tax-calculator":
      return inputs?.title || (inputs?.payerType
        ? `Tính thuế TMĐT ${inputs.payerType === "company" ? "Doanh nghiệp" : inputs.payerType === "individual" ? "Cá nhân KD" : "Hộ kinh doanh"} (${inputs.taxYear || 2026})`
        : "Tính thuế TMĐT 2026");

    default:
      return `Sử dụng công cụ ${TOOL_NAMES[tool] || tool}`;
  }
}

/**
 * Lấy toàn bộ số liệu thống kê AI của người dùng
 */
export async function getAiUsageStats(userId: string, filterTool?: string) {
  try {
    const startOfToday = getStartOfTodayVn();

    const userPromise = prisma.user.findUnique({
      where: { id: userId },
      select: { id: true, isVIP: true },
    });

    let todayCount = 0;
    let totalGenerated = 0;
    let rawActivities: any[] = [];

    const fetchStatsViaSql = async () => {
      try {
        const [todayRes, totalRes, actRes]: [any, any, any] = await Promise.all([
          prisma.$queryRawUnsafe(
            'SELECT COUNT(*)::int as count FROM "AiUsageLog" WHERE "userId" = $1 AND "createdAt" >= $2',
            userId,
            startOfToday
          ),
          filterTool
            ? prisma.$queryRawUnsafe(
                'SELECT COUNT(*)::int as count FROM "AiUsageLog" WHERE "userId" = $1 AND "tool" = $2',
                userId,
                filterTool
              )
            : prisma.$queryRawUnsafe(
                'SELECT COUNT(*)::int as count FROM "AiUsageLog" WHERE "userId" = $1',
                userId
              ),
          filterTool
            ? prisma.$queryRawUnsafe(
                'SELECT id, tool, "toolName", action, input, output, "createdAt" FROM "AiUsageLog" WHERE "userId" = $1 AND "tool" = $2 ORDER BY "createdAt" DESC LIMIT 50',
                userId,
                filterTool
              )
            : prisma.$queryRawUnsafe(
                'SELECT id, tool, "toolName", action, input, output, "createdAt" FROM "AiUsageLog" WHERE "userId" = $1 ORDER BY "createdAt" DESC LIMIT 10',
                userId
              ),
        ]);
        todayCount = Number(todayRes?.[0]?.count) || 0;
        totalGenerated = Number(totalRes?.[0]?.count) || 0;
        rawActivities = actRes || [];
      } catch (sqlErr) {
        console.warn("SQL fallback query error:", sqlErr);
      }
    };

    if (typeof (prisma as any).aiUsageLog?.count === "function") {
      try {
        const whereClause: any = { userId };
        if (filterTool) {
          whereClause.tool = filterTool;
        }

        [todayCount, totalGenerated, rawActivities] = await Promise.all([
          (prisma as any).aiUsageLog.count({
            where: {
              userId,
              createdAt: { gte: startOfToday },
            },
          }),
          (prisma as any).aiUsageLog.count({
            where: whereClause,
          }),
          (prisma as any).aiUsageLog.findMany({
            where: whereClause,
            orderBy: { createdAt: "desc" },
            take: filterTool ? 50 : 10,
            select: {
              id: true,
              tool: true,
              toolName: true,
              action: true,
              input: true,
              output: true,
              createdAt: true,
            },
          }),
        ]);
      } catch (ormErr) {
        console.warn("ORM aiUsageLog query failed, using SQL fallback:", ormErr);
        await fetchStatsViaSql();
      }
    } else {
      await fetchStatsViaSql();
    }

    const user = await userPromise;

    let globalDefaultLimit = 12;
    try {
      const setting: any = await prisma.$queryRawUnsafe(
        'SELECT "defaultDailyFreeLimit" FROM "SystemSetting" WHERE id = \'default\' LIMIT 1;'
      );
      if (setting?.[0]?.defaultDailyFreeLimit !== undefined) {
        globalDefaultLimit = Number(setting[0].defaultDailyFreeLimit) || 12;
      }
    } catch {}

    let dailyLimit = globalDefaultLimit;
    try {
      const rawUser: any = await (prisma as any).$queryRawUnsafe(
        'SELECT "dailyFreeLimit" FROM "User" WHERE id = $1',
        userId
      );
      if (rawUser && rawUser[0] && rawUser[0].dailyFreeLimit !== undefined) {
        dailyLimit = Number(rawUser[0].dailyFreeLimit) ?? globalDefaultLimit;
      }
    } catch {
      dailyLimit = globalDefaultLimit;
    }

    const remainingFree = user?.isVIP ? null : Math.max(0, dailyLimit - todayCount);

    const recentActivities = rawActivities.map((act) => {
      let parsedInput = null;
      if (act.input) {
        try {
          parsedInput = typeof act.input === "string" ? JSON.parse(act.input) : act.input;
        } catch {
          parsedInput = act.input;
        }
      }
      return {
        id: act.id,
        tool: act.tool,
        toolName: act.toolName,
        action: act.action,
        input: parsedInput,
        output: act.output,
        time: formatRelativeTime(act.createdAt),
        createdAt: act.createdAt instanceof Date ? act.createdAt.toISOString() : new Date(act.createdAt).toISOString(),
      };
    });

    return {
      todayCount,
      totalGenerated,
      dailyFreeLimit: dailyLimit,
      remainingFree,
      isVIP: !!user?.isVIP,
      recentActivities,
    };
  } catch (error) {
    console.error("Error fetching AI usage stats:", error);
    let fallbackLimit = 12;
    try {
      const setting: any = await prisma.$queryRawUnsafe(
        'SELECT "defaultDailyFreeLimit" FROM "SystemSetting" WHERE id = \'default\' LIMIT 1;'
      );
      if (setting?.[0]?.defaultDailyFreeLimit !== undefined) {
        fallbackLimit = Number(setting[0].defaultDailyFreeLimit) || 12;
      }
    } catch {}
    return {
      todayCount: 0,
      totalGenerated: 0,
      dailyFreeLimit: fallbackLimit,
      remainingFree: fallbackLimit,
      isVIP: false,
      recentActivities: [],
    };
  }
}

/**
 * Lưu bản ghi sử dụng AI vào Database
 */
export async function recordAiUsage(params: {
  userId: string;
  tool: string;
  toolName?: string;
  action?: string;
  input?: any;
  output?: string;
}) {
  try {
    const toolName = params.toolName || TOOL_NAMES[params.tool] || params.tool;
    const action = params.action || summarizeAiAction(params.tool, params.input);
    const inputStr = typeof params.input === "string" ? params.input : JSON.stringify(params.input || {});

    const logId = "log_" + Date.now() + "_" + Math.random().toString(36).substring(2, 8);

    if ((prisma as any).aiUsageLog?.create) {
      try {
        await (prisma as any).aiUsageLog.create({
          data: {
            id: logId,
            userId: params.userId,
            tool: params.tool,
            toolName,
            action,
            input: inputStr,
            output: params.output || null,
          },
        });
      } catch (ormErr) {
        await prisma.$executeRawUnsafe(
          'INSERT INTO "AiUsageLog" ("id", "userId", "tool", "toolName", "action", "input", "output", "createdAt") VALUES ($1, $2, $3, $4, $5, $6, $7, NOW())',
          logId,
          params.userId,
          params.tool,
          toolName,
          action,
          inputStr,
          params.output || null
        );
      }
    } else {
      await prisma.$executeRawUnsafe(
        'INSERT INTO "AiUsageLog" ("id", "userId", "tool", "toolName", "action", "input", "output", "createdAt") VALUES ($1, $2, $3, $4, $5, $6, $7, NOW())',
        logId,
        params.userId,
        params.tool,
        toolName,
        action,
        inputStr,
        params.output || null
      );
    }

    const startOfToday = getStartOfTodayVn();
    let todayCount = 1;
    let totalGenerated = 1;
    try {
      const [todayRes, totalRes]: [any, any] = await Promise.all([
        prisma.$queryRawUnsafe(
          'SELECT COUNT(*)::int as count FROM "AiUsageLog" WHERE "userId" = $1 AND "createdAt" >= $2',
          params.userId,
          startOfToday
        ),
        prisma.$queryRawUnsafe(
          'SELECT COUNT(*)::int as count FROM "AiUsageLog" WHERE "userId" = $1',
          params.userId
        ),
      ]);
      todayCount = Number(todayRes?.[0]?.count) || 1;
      totalGenerated = Number(totalRes?.[0]?.count) || 1;
    } catch {}

    return {
      success: true,
      logId,
      todayCount,
      totalGenerated,
    };
  } catch (error) {
    console.error("Error saving AI usage log:", error);
    return { success: false, error: "Failed to record AI usage" };
  }
}

import { NextResponse } from "next/server";
import OpenAI from "openai";
import { getSystemSettings } from "@/lib/system-settings";
import { prisma } from "@/lib/prisma";
import { getAiUsageStats, recordAiUsage } from "@/lib/ai-usage";
import { SeoError, SEO_SCHEMA, validateSeoInputs } from "./contract";
import { generateSeo } from "./generate";
import { finishSeo, reserveSeo, seoIdentity, type RunMetrics } from "./usage";

function publicError(error: unknown): SeoError {
  if (error instanceof SeoError) return error;
  if (error instanceof OpenAI.APIConnectionTimeoutError || (error instanceof Error && error.name === "AbortError")) return new SeoError("TIMEOUT", "AI xử lý quá lâu. Vui lòng thử lại; lượt dùng chưa bị trừ.", 504);
  if (error instanceof OpenAI.APIError) {
    if (error.status === 401 || error.status === 403) return new SeoError("AI_CONFIG_ERROR", "Cấu hình kết nối AI chưa hợp lệ. Vui lòng liên hệ quản trị viên.", 503);
    if (error.status === 429) return new SeoError("AI_BUSY", "Dịch vụ AI đang quá tải hoặc hết hạn mức. Vui lòng thử lại sau.", 503);
    if (error.status === 400 || error.status === 404) return new SeoError("AI_CONFIG_ERROR", "Model AI hoặc cấu hình đầu ra chưa được hỗ trợ. Vui lòng liên hệ quản trị viên.", 503);
    return new SeoError("AI_UNAVAILABLE", "Chưa kết nối được dịch vụ AI. Vui lòng thử lại sau.", 503);
  }
  return new SeoError("SERVICE_UNAVAILABLE", "Dịch vụ đang tạm gián đoạn. Vui lòng thử lại sau.", 503);
}

export async function handleSeo(req: Request, rawInputs: unknown) {
  const started = Date.now();
  let runId: string | undefined;
  let subject = "";
  const metrics: RunMetrics = { model: "", provider: "", inputTokens: 0, outputTokens: 0, durationMs: 0 };
  try {
    const origin = req.headers.get("origin");
    if ((origin && origin !== new URL(req.url).origin) || req.headers.get("sec-fetch-site") === "cross-site") {
      throw new SeoError("INVALID_ORIGIN", "Yêu cầu không hợp lệ.", 403);
    }
    const inputs = validateSeoInputs(rawInputs);
    const identity = await seoIdentity();
    subject = identity.id;

    // Kiểm tra định mức lượt dùng Free hàng ngày đối với tài khoản đăng nhập
    let currentUser: { id: string; isVIP: boolean; isLocked: boolean } | null = null;
    let userStats: any = null;
    if (!identity.anonymous && identity.userId) {
      currentUser = await prisma.user.findUnique({
        where: { id: identity.userId },
        select: { id: true, isVIP: true, isLocked: true },
      });

      if (currentUser?.isLocked) {
        throw new SeoError("ACCOUNT_LOCKED", "Tài khoản của bạn đã bị khóa bởi Quản trị viên.", 403);
      }

      if (currentUser && !currentUser.isVIP) {
        userStats = await getAiUsageStats(currentUser.id);
        if (userStats.remainingFree !== null && userStats.remainingFree <= 0) {
          throw new SeoError(
            "DAILY_LIMIT_EXCEEDED",
            `Tài khoản miễn phí được sử dụng ${userStats.dailyFreeLimit} lượt/ngày. Bạn đã dùng hết ${userStats.todayCount}/${userStats.dailyFreeLimit} lượt hôm nay. Vui lòng nâng cấp gói VIP để sử dụng không giới hạn!`,
            403
          );
        }
      }
    }

    runId = await reserveSeo(identity);
    const config = await getSystemSettings();
    const isOpenAI = config.isOpenAiActive;
    metrics.provider = isOpenAI ? "openai" : "ollama";
    metrics.model = isOpenAI ? config.openaiModel?.trim() || process.env.OPENAI_MODEL || "gpt-4o-mini" : process.env.OLLAMA_MODEL || "qwen2.5:7b";
    const apiKey = isOpenAI ? config.openaiApiKey?.trim() || process.env.OPENAI_API_KEY?.trim() : "ollama";
    if (!apiKey || apiKey === "dummy") throw new SeoError("AI_CONFIG_ERROR", "Dịch vụ AI chưa được cấu hình. Vui lòng liên hệ quản trị viên.", 503);
    const baseURL = isOpenAI ? config.openaiBaseUrl?.trim() || undefined : process.env.OLLAMA_BASE_URL || "http://127.0.0.1:11434/v1";
    const client = new OpenAI({ apiKey, baseURL, timeout: 45_000, maxRetries: 0 });
    const signal = AbortSignal.timeout(100_000);
    // Strict schema for the official API; compatible gateways/Ollama use JSON mode plus the same validator.
    let format: "schema" | "json" | "prompt" = isOpenAI && (!baseURL || new URL(baseURL).hostname === "api.openai.com") ? "schema" : "json";
    const output = await generateSeo(inputs, async prompt => {
      const request = () => client.chat.completions.create({
        model: metrics.model,
        messages: [{ role: "system", content: prompt }],
        ...(isOpenAI ? { max_completion_tokens: 3500 } : { max_tokens: 3500, temperature: 0.3 }),
        ...(format === "schema" ? { response_format: { type: "json_schema" as const, json_schema: { name: "seo_result", strict: true, schema: SEO_SCHEMA } } } :
          format === "json" ? { response_format: { type: "json_object" as const } } : {}),
      }, { signal });
      let completion;
      try { completion = await request(); }
      catch (error) {
        // Some compatible providers lack response_format; do not retry authentication/quota errors.
        if (error instanceof OpenAI.APIError && error.status === 400 && /response_format|json_schema|json_object/i.test(error.message) && format !== "prompt") {
          format = "prompt";
          completion = await request();
        } else throw error;
      }
      const choice = completion.choices[0];
      return { content: choice?.message.content ?? null, finishReason: choice?.finish_reason ?? "", refused: !!choice?.message.refusal,
        inputTokens: completion.usage?.prompt_tokens ?? 0, outputTokens: completion.usage?.completion_tokens ?? 0 };
    }, (input, outputTokens) => { metrics.inputTokens += input; metrics.outputTokens += outputTokens; });
    metrics.durationMs = Date.now() - started;
    const successes = await finishSeo(subject, runId, true, metrics, null);

    // Ghi nhận lượt dùng AI vào AiUsageLog nếu đã đăng nhập
    if (currentUser) {
      try {
        await recordAiUsage({
          userId: currentUser.id,
          tool: "seo-optimizer",
          toolName: "AI Tối Ưu SEO",
          action: `Tối ưu SEO (${inputs.platform === "tiktok" ? "TikTok Shop" : "Shopee"}): ${inputs.productName}`,
          input: inputs,
          output: typeof output === "string" ? output : JSON.stringify(output),
        });
      } catch (logErr) {
        console.error("Error logging AI usage in SEO:", logErr);
      }
    }

    const updatedStats = currentUser && !currentUser.isVIP ? await getAiUsageStats(currentUser.id) : null;

    return NextResponse.json({
      success: true,
      data: output,
      remaining: currentUser
        ? (currentUser.isVIP ? null : updatedStats?.remainingFree)
        : (identity.anonymous ? Math.max(0, 2 - successes) : null),
      dailyFreeLimit: updatedStats?.dailyFreeLimit ?? userStats?.dailyFreeLimit,
      isVIP: currentUser ? currentUser.isVIP : false,
    }, { headers: { "Cache-Control": "no-store" } });
  } catch (error) {
    const failure = publicError(error);
    metrics.durationMs = Date.now() - started;
    if (runId) {
      try { await finishSeo(subject, runId, false, metrics, failure.code); }
      catch { console.error("seo_usage_finalize_failed", { runId, code: failure.code }); }
    }
    if (failure.status >= 500) console.error("seo_request_failed", { runId, code: failure.code, validationHint: failure.validationHint, ...metrics });
    return NextResponse.json({
      success: false,
      code: failure.code,
      error: failure.message,
      details: failure.code === "DAILY_LIMIT_EXCEEDED" ? { actionUrl: "/profile#pricing-section" } : undefined,
    }, {
      status: failure.status,
      headers: { "Cache-Control": "no-store", ...(failure.status === 429 ? { "Retry-After": "60" } : {}) },
    });
  }
}

import { prisma } from "@/lib/prisma";

export interface SystemSettingData {
  id: string;
  adminPassword?: string | null;
  openaiApiKey: string | null;
  openaiModel: string;
  openaiBaseUrl: string | null;
  isOpenAiActive: boolean;
  createdAt: Date;
  updatedAt: Date;
}

export const DEFAULT_SYSTEM_SETTINGS = {
  id: "default",
  adminPassword: "bigman123",
  openaiApiKey: "",
  openaiModel: "gpt-4o-mini",
  openaiBaseUrl: "",
  isOpenAiActive: true,
};

/**
 * Lấy cấu hình hệ thống từ Database.
 * Hỗ trợ cả Prisma ORM và Direct SQL Fallback (tự phục hồi nếu instance PrismaClient cũ).
 */
export async function getSystemSettings(): Promise<SystemSettingData> {
  try {
    // 1. Thử dùng Prisma Model nếu có sẵn
    if ((prisma as any).systemSetting?.findUnique) {
      const setting = await (prisma as any).systemSetting.findUnique({
        where: { id: "default" },
      });
      if (setting) return setting;
    }

    // 2. Direct SQL Query Fallback (chạy trực tiếp trên PostgreSQL, an toàn 100%)
    const rows: any = await prisma.$queryRawUnsafe(
      `SELECT * FROM "SystemSetting" WHERE id = 'default' LIMIT 1;`
    );
    if (rows && rows.length > 0) {
      return rows[0];
    }

    // 3. Nếu chưa có bản ghi, tạo bản ghi mặc định
    const envKey = process.env.OPENAI_API_KEY?.trim().replace(/^["']|["']$/g, "") || null;
    const envModel = process.env.OPENAI_MODEL?.trim() || "gpt-4o-mini";
    const envStatus = process.env.OpenAIStatus?.trim().toLowerCase();
    const envIsOpenAi = envStatus === undefined ? true : envStatus === "true";

    await prisma.$executeRawUnsafe(
      `INSERT INTO "SystemSetting" ("id", "openaiApiKey", "openaiModel", "openaiBaseUrl", "isOpenAiActive", "createdAt", "updatedAt")
       VALUES ('default', $1, $2, null, $3, NOW(), NOW())
       ON CONFLICT ("id") DO NOTHING;`,
      envKey,
      envModel,
      envIsOpenAi
    );

    const createdRows: any = await prisma.$queryRawUnsafe(
      `SELECT * FROM "SystemSetting" WHERE id = 'default' LIMIT 1;`
    );
    if (createdRows && createdRows.length > 0) {
      return createdRows[0];
    }

    return {
      id: "default",
      openaiApiKey: envKey,
      openaiModel: envModel,
      openaiBaseUrl: null,
      isOpenAiActive: envIsOpenAi,
      createdAt: new Date(),
      updatedAt: new Date(),
    };
  } catch (error) {
    console.error("Error fetching system settings:", error);
    return {
      id: "default",
      openaiApiKey: process.env.OPENAI_API_KEY?.trim().replace(/^["']|["']$/g, "") || null,
      openaiModel: process.env.OPENAI_MODEL?.trim() || "gpt-4o-mini",
      openaiBaseUrl: null,
      isOpenAiActive: true,
      createdAt: new Date(),
      updatedAt: new Date(),
    };
  }
}

/**
 * Cập nhật cấu hình hệ thống
 * Hỗ trợ cả Prisma ORM và Direct SQL Fallback (không bao giờ lỗi upsert undefined)
 */
export async function updateSystemSettings(data: {
  adminPassword?: string | null;
  openaiApiKey?: string | null;
  openaiModel?: string;
  openaiBaseUrl?: string | null;
  isOpenAiActive?: boolean;
}): Promise<SystemSettingData> {
  const current = await getSystemSettings();

  const nextAdminPassword =
    data.adminPassword !== undefined
      ? data.adminPassword ? data.adminPassword.trim() : null
      : current.adminPassword || "bigman123";
  const nextApiKey =
    data.openaiApiKey !== undefined
      ? data.openaiApiKey ? data.openaiApiKey.trim() : null
      : current.openaiApiKey;
  const nextModel =
    data.openaiModel !== undefined
      ? data.openaiModel.trim()
      : current.openaiModel || "gpt-4o-mini";
  const nextBaseUrl =
    data.openaiBaseUrl !== undefined
      ? data.openaiBaseUrl ? data.openaiBaseUrl.trim() : null
      : current.openaiBaseUrl;
  const nextActive =
    data.isOpenAiActive !== undefined
      ? Boolean(data.isOpenAiActive)
      : current.isOpenAiActive;

  // 1. Thử dùng Prisma ORM nếu model systemSetting đã nạp vào client
  if ((prisma as any).systemSetting?.upsert) {
    try {
      return await (prisma as any).systemSetting.upsert({
        where: { id: "default" },
        update: {
          adminPassword: nextAdminPassword,
          openaiApiKey: nextApiKey,
          openaiModel: nextModel,
          openaiBaseUrl: nextBaseUrl,
          isOpenAiActive: nextActive,
        },
        create: {
          id: "default",
          adminPassword: nextAdminPassword,
          openaiApiKey: nextApiKey,
          openaiModel: nextModel,
          openaiBaseUrl: nextBaseUrl,
          isOpenAiActive: nextActive,
        },
      });
    } catch (ormErr) {
      console.warn("Prisma ORM upsert failed, falling back to direct SQL:", ormErr);
    }
  }

  // 2. Direct SQL Upsert Fallback (chạy độc lập, không phụ thuộc vào PrismaClient instance cache)
  await prisma.$executeRawUnsafe(
    `INSERT INTO "SystemSetting" ("id", "adminPassword", "openaiApiKey", "openaiModel", "openaiBaseUrl", "isOpenAiActive", "createdAt", "updatedAt")
     VALUES ('default', $1, $2, $3, $4, $5, NOW(), NOW())
     ON CONFLICT ("id") DO UPDATE
     SET "adminPassword" = $1, "openaiApiKey" = $2, "openaiModel" = $3, "openaiBaseUrl" = $4, "isOpenAiActive" = $5, "updatedAt" = NOW();`,
    nextAdminPassword,
    nextApiKey,
    nextModel,
    nextBaseUrl,
    nextActive
  );

  const updatedRows: any = await prisma.$queryRawUnsafe(
    `SELECT * FROM "SystemSetting" WHERE id = 'default' LIMIT 1;`
  );

  if (updatedRows && updatedRows.length > 0) {
    return updatedRows[0];
  }

  return {
    id: "default",
    adminPassword: nextAdminPassword,
    openaiApiKey: nextApiKey,
    openaiModel: nextModel,
    openaiBaseUrl: nextBaseUrl,
    isOpenAiActive: nextActive,
    createdAt: current.createdAt || new Date(),
    updatedAt: new Date(),
  };
}

/**
 * Xác thực mật khẩu Admin
 */
export async function verifyAdminPassword(password: string): Promise<boolean> {
  try {
    const settings = await getSystemSettings();
    const currentPass = settings.adminPassword || "bigman123";
    return password === currentPass;
  } catch {
    return password === "bigman123";
  }
}

/**
 * Đổi mật khẩu Admin an toàn
 */
export async function changeAdminPassword(
  currentPassword: string,
  newPassword: string
): Promise<{ success: boolean; error?: string }> {
  try {
    const isCorrect = await verifyAdminPassword(currentPassword);
    if (!isCorrect) {
      return { success: false, error: "Mật khẩu quản trị hiện tại không chính xác!" };
    }
    if (!newPassword || newPassword.trim().length < 6) {
      return { success: false, error: "Mật khẩu mới phải có tối thiểu 6 ký tự!" };
    }
    if (newPassword.trim() === currentPassword.trim()) {
      return { success: false, error: "Mật khẩu mới không được trùng với mật khẩu hiện tại!" };
    }

    await updateSystemSettings({ adminPassword: newPassword.trim() });
    return { success: true };
  } catch (err: any) {
    return { success: false, error: err?.message || "Không thể cập nhật mật khẩu quản trị." };
  }
}

/**
 * Lấy nhanh OpenAI Token / API Key
 */
export async function getOpenAiToken(): Promise<{
  token: string;
  apiKey: string;
  model: string;
  baseURL?: string;
  isOpenAiActive: boolean;
}> {
  const settings = await getSystemSettings();
  const rawKey = settings.openaiApiKey || process.env.OPENAI_API_KEY?.trim().replace(/^["']|["']$/g, "") || "";

  return {
    token: rawKey,
    apiKey: rawKey,
    model: settings.openaiModel || "gpt-4o-mini",
    baseURL: settings.openaiBaseUrl || undefined,
    isOpenAiActive: settings.isOpenAiActive,
  };
}

import { prisma } from "@/lib/prisma";
import { DEFAULT_VIP_PLANS, VipPlanItem } from "@/lib/vip-plans";

/**
 * Lấy danh sách gói VIP đang hoạt động, nếu DB chưa có gói nào sẽ tự khởi tạo 3 gói mặc định
 */
export async function getActiveVipPlans(): Promise<VipPlanItem[]> {
  const existing = await prisma.vipPlan.findMany({
    where: { active: true },
    orderBy: { order: "asc" },
  });

  if (existing.length > 0) {
    return existing as VipPlanItem[];
  }

  // Khởi tạo tự động nếu DB chưa có
  for (const plan of DEFAULT_VIP_PLANS) {
    const { id, createdAt, updatedAt, ...planData } = plan;
    await prisma.vipPlan.upsert({
      where: { slug: plan.slug },
      update: {},
      create: planData,
    });
  }

  const seeded = await prisma.vipPlan.findMany({
    where: { active: true },
    orderBy: { order: "asc" },
  });

  return seeded as VipPlanItem[];
}
